import React from 'react';

const styles = {
  page: { 
    fontFamily: "Arial, Helvetica, sans-serif", 
    color: "#EAEFF8", 
    background: "#000000", 
    overflow: "hidden" 
  },
  hero: { 
    minHeight: "520px", 
    backgroundImage: "linear-gradient(90deg, rgba(0,0,0,.96) 0%, rgba(0,0,0,.8) 45%, rgba(0,0,0,.2) 100%), url('https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1800&q=90')", 
    backgroundSize: "cover", 
    backgroundPosition: "center", 
    display: "flex", 
    alignItems: "center", 
    padding: "70px 6%", 
    boxSizing: "border-box" 
  },
  heroContent: { maxWidth: "590px", color: "#fff" },
  eyebrow: { 
    fontSize: "14px", 
    letterSpacing: "4px", 
    fontWeight: "700", 
    marginBottom: "15px",
    color: "#00D4FF"
  },
  heroTitle: { 
    fontFamily: "Georgia, serif", 
    fontSize: "50px", 
    lineHeight: "1.02", 
    margin: "0 0 22px", 
    fontWeight: "700" 
  },
  heroText: { 
