    padding: "28px", 
    background: "#05050A", 
    borderRadius: "12px", 
    display: "grid", 
    gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", 
    gap: "0", 
    boxSizing: "border-box",
    border: "1px solid #1A1A2E"
  },
  feature: { 
