export default function About() {
  return (
    <div style={styles.page}>
      {/* CSS for RGB Infinity animations and Hover Transforms */}
      <style dangerouslySetInnerHTML={{__html: `
        @keyframes rgb-infinity {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        
        .rgb-text {
          background: linear-gradient(90deg, #ff0000, #ff7300, #fffb00, #48ff00, #00ffd5, #002bff, #7a00ff, #ff00c8, #ff0000);
          background-size: 200% auto;
          color: transparent;
          -webkit-background-clip: text;
          background-clip: text;
          animation: rgb-infinity 5s linear infinite;
        }

        .action-btn {
          display: inline-flex;
          align-items: center;
          gap: 15px;
          padding: 15px 28px;
          border-radius: 30px;
          background: #08083B;
          color: #ffffff;
          font-weight: 700;
          font-size: 15px;
          border: none;
          cursor: pointer;
          position: relative;
          z-index: 1;
          transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
          text-decoration: none;
        }

        .action-btn::before {
          content: "";
          position: absolute;
          inset: -3px;
          border-radius: 35px;
          background: linear-gradient(90deg, #ff0000, #ff7300, #fffb00, #48ff00, #00ffd5, #002bff, #7a00ff, #ff00c8, #ff0000);
          background-size: 200% auto;
          z-index: -1;
          animation: rgb-infinity 3s linear infinite;
          opacity: 0;
          transition: opacity 0.3s ease;
        }

        .action-btn:hover {
          transform: translateY(-5px) scale(1.03);
          box-shadow: 0 10px 25px rgba(0, 0, 0, 0.6);
        }

        .action-btn:hover::before {
          opacity: 1;
        }

        .action-btn-inner {
          background: #08083B;
          position: absolute;
          inset: 2px;
          border-radius: 28px;
          z-index: -1;
        }

        .image-hover {
          transition: transform 0.5s ease;
        }
        
        .image-hover:hover {
          transform: scale(1.02);
        }
      `}} />

      <section style={styles.hero}>
        <div style={styles.heroContent}>
          <div style={styles.eyebrow}>ABOUT US</div>
          <h1 style={styles.heroTitle}>
            Building<br/>
            Brighter Futures<br/>
            <span className="rgb-text">Together</span>
          </h1>
          <p style={styles.heroText}>
            At Vighnavi Academy, we believe education is more than learning — it’s a journey towards confidence, opportunities and a better tomorrow.
          </p>
          <button className="action-btn">
            <span className="action-btn-inner"></span>
            Our Story <span>→</span>
          </button>
        </div>
      </section>

      <section style={styles.stats}>
        <div style={styles.stat}>
          <span style={styles.statIcon}>🎓</span>
          <p style={styles.statNumber}>5,000+</p>
          <div style={styles.statLabel}>Happy Learners</div>
        </div>
        <div style={styles.stat}>
          <span style={styles.statIcon}>👥</span>
          <p style={styles.statNumber}>50+</p>
          <div style={styles.statLabel}>Expert Mentors</div>
        </div>
        <div style={styles.stat}>
          <span style={styles.statIcon}>📖</span>
          <p style={styles.statNumber}>100+</p>
          <div style={styles.statLabel}>Courses</div>
        </div>
        <div style={{...styles.stat, borderRight: "none"}}>
          <span style={styles.statIcon}>🏆</span>
          <p style={styles.statNumber}>95%</p>
          <div style={styles.statLabel}>Success Rate</div>
        </div>
      </section>

      <section style={styles.story}>
        <div style={styles.imageWrap}>
          <img 
            className="image-hover" 
            style={styles.storyImage} 
            src="https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=1000&q=90" 
            alt="Vighnavi Academy"
          />
          <div style={styles.quote}>
            “Education is the foundation for a brighter tomorrow.”
          </div>
        </div>
        <div style={styles.storyContent}>
          <div style={{...styles.eyebrow, color: "#00D4FF"}}>OUR STORY</div>
          <h2 style={styles.sectionTitle}>
            Empowering Learners.<br/>
            <span className="rgb-text">Enriching Lives.</span>
          </h2>
          <p style={styles.storyText}>
            Vighnavi Academy was founded with a simple yet powerful vision — to make quality education accessible to everyone. We started as a small initiative with a big dream: to create a learning platform that nurtures talent, builds skills, and unlocks opportunities.
          </p>
          <p style={styles.storyText}>
            Today, we are proud to be a trusted name in education, helping thousands of learners achieve their goals through industry-relevant courses, expert guidance, and a learner-first approach.
          </p>
          <button className="action-btn" style={{ marginTop: "10px" }}>
            <span className="action-btn-inner"></span>
            Our Mission & Vision <span>→</span>
          </button>
        </div>
      </section>

      <section style={styles.features}>
        <div style={styles.feature}>
          <span style={styles.featureIcon}>🎯</span>
          <h3 style={styles.featureTitle}>Our Mission</h3>
          <p style={styles.featureText}>To provide high-quality, practical and accessible education that empowers individuals to achieve their personal and professional goals.</p>
        </div>
        <div style={styles.feature}>
          <span style={styles.featureIcon}>👁️</span>
          <h3 style={styles.featureTitle}>Our Vision</h3>
          <p style={styles.featureText}>To be a leading learning platform recognized for transforming lives through education and innovation.</p>
        </div>
        <div style={{...styles.feature, borderRight: "none"}}>
          <span style={styles.featureIcon}>💎</span>
          <h3 style={styles.featureTitle}>Our Values</h3>
          <p style={styles.featureText}>We stand for integrity, excellence, inclusivity and a strong commitment to our learners’ success.</p>
        </div>
      </section>

      <section style={styles.cta}>
        <div style={styles.ctaContent}>
          <h2 style={styles.ctaTitle}>
            Let’s Shape<br/>
            <span className="rgb-text">a Brighter Tomorrow</span>
          </h2>
          <p style={styles.ctaText}>Join Vighnavi Academy and take the next step towards your goals.</p>
          <button className="action-btn">
            <span className="action-btn-inner"></span>
            Explore Our Courses <span>→</span>
          </button>
        </div>
      </section>
    </div>
  );
}
